def reverse_string(s):
    return s[::-1]

print(reverse_string("Hindi"))  # output: idniH

def count_vowels(s):
    count = 0
    for ch in s:
        if ch.lower() in "aeiou":
            count += 1
    return count

print(count_vowels("hello world"))  # output: 3

def char_count(s):
    counts = {}
    for ch in s:
        counts[ch] = counts.get(ch, 0) + 1
    return counts

print(char_count("banana"))  # output: {'b':1, 'a':3, 'n':2}

def to_upper(s):
    result = ""
    for ch in s:
        if 97 <= ord(ch) <= 122:
            result += chr(ord(ch) - 32)
        else:
            result += ch
    return result

print(to_upper("namaste"))  # output: NAMASTE

def count_words(s):
    words = s.split()
    return len(words)

print(count_words("Main coding seekh raha hu"))  # output: 4

def swap_first_last(s):
    words = s.split()
    if len(words) < 2:
        return s
    words[0], words[-1] = words[-1], words[0]
    return " ".join(words)

print(swap_first_last("a b c d"))  # output: d b c a

def capitalize_words(s):
    words = s.split()
    result = []
    for w in words:
        if w:
            result.append(w[0].upper() + w[1:])
        else:
            result.append(w)
    return " ".join(result)

print(capitalize_words("hindi coding hai acchi"))  # output: Hindi Coding Hai Acchi

def remove_spaces(s):
    return s.replace(" ", "")

print(remove_spaces("hello world"))  # output: helloworld

def has_duplicates(s):
    seen = set()
    for ch in s:
        if ch in seen:
            return True
        seen.add(ch)
    return False

print(has_duplicates("abcd"))  # output: False
print(has_duplicates("aabb"))  # output: True

def to_snake_case(s):
    result = []
    for i, ch in enumerate(s):
        if ch.isupper() and i > 0:
            result.append("_")
        result.append(ch.lower())
    return "".join(result)

print(to_snake_case("HelloWorld"))  # output: hello_world

def sum_digits_string(s):
    total = 0
    for ch in s:
        if ch.isdigit():
            total += int(ch)
    return total

print(sum_digits_string("abc123def45"))  # output: 15

def count_word(s, word):
    return s.lower().split().count(word.lower())

print(count_word("aap aap aap acche ho", "aap"))  # output: 3

def repeat_string(s, n):
    return s * n

print(repeat_string("ha", 3))  # output: hahaha

def str_length(s):
    count = 0
    for _ in s:
        count += 1
    return count

